*{box-sizing:border-box} :root{--bg:#090b12;--panel:#10131c;--line:#252936;--muted:#777d8e;--text:#e8e5de;--red:#e85b50;--amber:#e3b46b;--mono:'DM Mono',monospace;--sans:'Space Grotesk',sans-serif}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(ellipse at 50% -20%,#24202a 0,#10111a 37%,var(--bg) 75%);color:var(--text);font-family:var(--sans);min-height:100vh}.shell{max-width:1392px;margin:0 auto;padding:0 40px}.topbar{height:68px;border-bottom:1px solid #252631;display:flex;align-items:center;justify-content:space-between;font:10px var(--mono);letter-spacing:.13em;color:#9294a0}.brand{color:#e5e2dc;text-decoration:none;font-weight:500;letter-spacing:.18em}.brand-mark{color:var(--red);font-size:17px;margin-right:8px;vertical-align:-2px}.brand-divider{color:#4b4d57;margin:0 8px}.top-meta{display:flex;align-items:center;gap:10px}.live-dot,.status-dot{width:7px;height:7px;border-radius:50%;background:#7cbd83;box-shadow:0 0 9px #7cbd8370}.meta-sep{color:#555}.sound-button{background:none;color:#b9bac1;border:1px solid #343743;padding:8px 11px;font:10px var(--mono);letter-spacing:.08em;cursor:pointer}.sound-button:hover{border-color:var(--red);color:white}.intro-row{display:flex;align-items:end;justify-content:space-between;padding:31px 0 23px}.eyebrow,.panel-heading,.status-label{font:10px var(--mono);letter-spacing:.16em;color:#9697a1}.eyebrow{display:flex;gap:12px;align-items:center}.eyebrow i{height:1px;width:25px;background:#464854}.title-block h1{font-size:clamp(28px,3.8vw,47px);line-height:1;margin:10px 0 7px;letter-spacing:.05em;font-weight:700}.title-block h1 em,.objective-panel h2 em{font-style:normal;color:var(--red)}.subtitle{color:#8e909a;font:12px var(--mono);margin:0}.status-card{border:1px solid #292d38;background:#10121b;padding:12px 15px;min-width:215px;margin-bottom:1px}.status-label{font-size:8px;display:block;margin-bottom:8px}.status-card strong{display:flex;align-items:center;gap:8px;font:10px var(--mono);letter-spacing:.1em;color:#d9d4ca}.status-dot{width:6px;height:6px;background:#d3a75d}.status-note{font:10px var(--mono);color:#727583;display:block;margin-top:7px}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 286px;gap:17px;align-items:stretch}.game-frame{border:1px solid #2a2d37;background:#0b0d14;min-width:0;box-shadow:0 24px 70px #0006}.frame-top,.frame-bottom{height:34px;padding:0 14px;display:flex;align-items:center;justify-content:space-between;color:#878a96;font:9px var(--mono);letter-spacing:.12em}.frame-top{border-bottom:1px solid #282b35}.frame-bottom{border-top:1px solid #282b35;color:#838792}.frame-divider{color:#50515a;margin:0 7px}.rec-dot{display:inline-block;width:6px;height:6px;background:var(--red);border-radius:50%;margin-right:7px;box-shadow:0 0 8px #f3544a}.frame-bottom b{color:#e1d6c3;font-weight:400}.unit{color:#535762}.signal-icon{color:var(--amber);font-size:13px;margin-right:5px}.bottom-center{color:#b16b64;letter-spacing:.18em}.canvas-wrap{position:relative;overflow:hidden;background:#10140f;line-height:0}canvas{display:block;width:100%;height:auto;aspect-ratio:8/5;image-rendering:pixelated}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 45%,#06070bcc 100%);box-shadow:inset 0 0 60px #06070b88}.screen-overlay,.result-overlay{position:absolute;inset:0;z-index:4;display:flex;align-items:center;justify-content:center;text-align:center;background:linear-gradient(90deg,#090b12d9,#090b12aa 48%,#090b128a)}.screen-overlay.hidden,.result-overlay.hidden{display:none}.overlay-grain{position:absolute;inset:0;opacity:.13;pointer-events:none;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.3'/%3E%3C/svg%3E")}.overlay-content{position:relative;padding:25px 20px;line-height:1.4}.overlay-tag{display:flex;justify-content:center;gap:24px;color:#a8a2a0;font:9px var(--mono);letter-spacing:.16em}.title-sigil{font-size:21px;color:var(--red);margin:15px 0 4px;text-shadow:0 0 20px #ec554b}.overlay-kicker{font:9px var(--mono);letter-spacing:.23em;color:var(--red);margin:0 0 10px}.overlay-content h2,.result-card h2{font-size:clamp(30px,5vw,54px);line-height:.96;letter-spacing:.02em;margin:0;font-weight:700;text-shadow:0 3px 20px #000}.overlay-content h2 em{font-style:normal;color:var(--red)}.overlay-copy{font:11px/1.8 var(--mono);color:#b5b3b0;margin:17px 0 19px}.start-button{background:var(--red);border:0;color:#171014;padding:13px 18px;font:11px var(--mono);font-weight:500;letter-spacing:.12em;cursor:pointer;transition:all .2s}.start-button span{font-size:16px;margin-left:12px}.start-button:hover{background:#ff776a;transform:translateY(-2px);box-shadow:0 7px 25px #e85b5055}.overlay-hint{margin-top:17px;color:#777b83;font:8px var(--mono);letter-spacing:.1em}.overlay-hint span{color:var(--red);margin:0 5px}.result-overlay{background:#08090dcc;z-index:5}.result-card{line-height:1.5;padding:30px}.result-eyebrow{font:9px var(--mono);letter-spacing:.2em;color:var(--amber)}.result-card h2{font-size:36px;margin:12px 0}.result-card p{color:#a7a5a1;font:11px var(--mono);margin:0 0 22px}.sidebar{display:flex;flex-direction:column;gap:11px}.panel{background:linear-gradient(145deg,#12151f,#0e1119);border:1px solid #282c37;padding:15px 16px}.panel-heading{display:flex;justify-content:space-between;font-size:8px}.panel-index{color:#6e7280}.objective-panel h2{font-size:22px;line-height:1.1;margin:18px 0 9px;letter-spacing:.01em}.objective-panel p{font:10px/1.7 var(--mono);color:#8d909b;margin:0 0 16px}.progress-line{height:3px;background:#292d38}.progress-line div{height:100%;width:0;background:var(--red);transition:width .3s;box-shadow:0 0 9px #e85b5077}.collect-count{display:flex;align-items:center;gap:8px;margin-top:8px}.collect-count strong{font:20px var(--mono);color:var(--amber)}.collect-count span{font:8px var(--mono);letter-spacing:.1em;color:#838693}.signal-panel{padding-bottom:10px}.radar{height:103px;position:relative;overflow:hidden;background:#0a1115;margin-top:12px;border:1px solid #252e32;background-image:radial-gradient(circle at center,transparent 0 17px,#35433c 18px 18.5px,transparent 19px 35px,#35433c 36px 36.5px,transparent 37px),linear-gradient(90deg,transparent 49.5%,#35433c 50%,transparent 50.5%),linear-gradient(0deg,transparent 49.5%,#35433c 50%,transparent 50.5%)}.radar:after{content:'';position:absolute;inset:0;background:radial-gradient(ellipse at center,#15332655,transparent 72%)}.radar-sweep{position:absolute;z-index:1;left:50%;top:50%;height:50%;width:50%;transform-origin:0 0;background:conic-gradient(from 0deg,#7cc78c44,#7cc78c00 75deg);animation:sweep 4s linear infinite}@keyframes sweep{to{transform:rotate(360deg)}}.radar-player,.radar-threat,.radar-blip{position:absolute;z-index:2;width:5px;height:5px;border-radius:50%;background:#8ad99c;box-shadow:0 0 8px #8ad99c}.radar-player{left:50%;top:50%}.radar-threat{background:#f15b53;box-shadow:0 0 10px #f15b53;transition:all .3s}.radar-threat.hidden{display:none}.radar-blip{width:3px;height:3px;background:#bd9c5e;box-shadow:0 0 6px #bd9c5e}.blip-a{left:28%;top:35%}.blip-b{left:72%;top:63%}.radar-caption{display:flex;justify-content:space-between;margin-top:7px;color:#777d86;font:8px var(--mono);letter-spacing:.1em}.radar-caption i{display:inline-block;width:5px;height:5px;border-radius:50%;background:#8ad99c;margin-right:4px}.radar-caption .key-threat{background:#f15b53}.log-panel{padding:13px 16px}.log-entry{display:flex;gap:10px;font:9px var(--mono);color:#c4c0b9;margin-top:12px}.log-entry.dim{margin-top:8px;color:#666a76}.log-time{color:#b77e66}.controls-card{border:1px solid #282c37;background:#10131b;padding:12px 15px;margin-top:auto}.controls-title{display:flex;justify-content:space-between;font:8px var(--mono);letter-spacing:.13em;color:#90929d;margin-bottom:9px}.controls-title span{font-size:11px;color:#555a66}.key-row{display:flex;align-items:center;gap:4px;margin:6px 0}.keycap{height:19px;min-width:19px;padding:0 5px;display:inline-flex;align-items:center;justify-content:center;border:1px solid #3b3e49;border-bottom-width:2px;color:#c5c6ca;font:9px var(--mono);background:#191c25}.keycap.wide{min-width:54px}.key-label{font:8px var(--mono);color:#777b86;margin-left:6px;letter-spacing:.03em}footer{height:50px;display:flex;align-items:center;justify-content:space-between;color:#656975;font:8px var(--mono);letter-spacing:.12em}footer b{color:var(--red);padding:0 5px}footer a{color:#9597a0;text-decoration:none}.mobile-pad,.touch-run{display:none}.screen-overlay~.vignette{z-index:3;pointer-events:none}
